 1	/**
 2	 * Tests for the WebSocket polyfill utility.
 3	 *
 4	 * Verifies that the CLI WebSocket utility provides a working WebSocket
 5	 * constructor regardless of Node version (uses `ws` package as fallback
 6	 * when globalThis.WebSocket is unavailable, i.e. Node < 22).
 7	 *
 8	 * Task: @01KK617H896Z5RHSCVA51G9QFQ
 9	 * Spec: @cli-agent-commands
10	 */
11	
12	import { describe, it, expect, afterEach, vi } from "vitest";
13	import { getWebSocketCtor } from "../src/cli/websocket.js";
14	
15	describe("cli/websocket polyfill", () => {
16	  afterEach(() => {
17	    vi.unstubAllGlobals();
18	  });
19	
20	  it("returns a WebSocket constructor", () => {
21	    const WS = getWebSocketCtor();
22	    expect(typeof WS).toBe("function");
23	  });
24	
25	  it("prefers globalThis.WebSocket when available", () => {
26	    class FakeWS { constructor(_url: string) { /* noop */ } }
27	    vi.stubGlobal("WebSocket", FakeWS);
28	
29	    const WS = getWebSocketCtor();
30	    expect(WS).toBe(FakeWS);
31	  });
32	
33	  it("can establish a real WebSocket connection via the fallback", async () => {
34	    // Use the ws Server to verify the exported constructor can connect
35	    const { WebSocketServer } = await import("ws");
36	    const { createServer } = await import("node:http");
37	
38	    const server = createServer();
39	    const wss = new WebSocketServer({ server });
40	    let serverReceived: string | undefined;
41	
42	    wss.on("connection", (ws) => {
43	      ws.on("message", (data) => {
44	        serverReceived = data.toString();
45	        ws.send("pong");
46	      });
47	    });
48	
49	    await new Promise<void>((resolve) => server.listen(0, resolve));
50	    const port = (server.address() as { port: number }).port;
51	
52	    try {
53	      const WS = getWebSocketCtor();
54	      const ws = new WS(`ws://localhost:${port}`);
55	      const result = await new Promise<string>((resolve, reject) => {
56	        const timeout = setTimeout(() => reject(new Error("timeout")), 5000);
57	        ws.onopen = () => {
58	          ws.send("ping");
59	        };
60	        ws.onmessage = (event: MessageEvent) => {
61	          clearTimeout(timeout);
62	          resolve(event.data as string);
63	          ws.close();
64	        };
65	        ws.onerror = () => {
66	          clearTimeout(timeout);
67	          reject(new Error("WebSocket error"));
68	        };
69	      });
70	
71	      expect(result).toBe("pong");
72	      expect(serverReceived).toBe("ping");
73	    } finally {
74	      wss.close();
75	      server.close();
76	    }
77	  });
78	});

